    if (e.kind === 'message') return renderMessage(e);
    if (e.kind === 'tool_call') return renderToolCall(e);
    if (e.kind === 'tool_result') { if (attachResult(e)) return null; return renderStatus(e); }
    if (e.kind === 'reasoning') return renderReasoning(e);
